import os
final class LockerFeed { var onChange: ((Int) -> Void)? }
final class StatusPanel {
    let feed: LockerFeed
    var free = 0
    let logger = Logger(subsystem: "dev.synapso.demo",
                        category: "LockerStatus")
    init(feed: LockerFeed) {
        self.feed = feed
        feed.onChange = { [weak self] value in
            self?.free = value
            self?.logger.debug("Свободно: \(value)")
        }
    }
    deinit { feed.onChange = nil }
}
let feed = LockerFeed()
var panel: StatusPanel? = StatusPanel(feed: feed)
weak var witness = panel
feed.onChange?(3)
assert(panel?.free == 3)
panel = nil
assert(witness == nil)
assert(feed.onChange == nil)

weak self не создаёт обратное сильное ребро. После исчезновения последнего внешнего владельца deinit убирает callback; проверки разделяют обновление и время жизни.

